	@ParameterizedTest(name = "{0}/{1}")
	@MethodSource("cases")
	void matchesIndependentGraphNodeJoinOracle(Case test, Mode mode) {
		System.setProperty(NATIVE, Boolean.toString(mode.nativeEngine));
		System.setProperty(IDS, Boolean.toString(mode.ids));
		// Adjacency is intentionally off: this discrepancy exists before the new node-domain producer.
		repository = new SailRepository(new LmdbStore(directory,
				new LmdbStoreConfig("spoc,posc,ospc").setNativeEvaluationEnabled(true)
						.setDirectAdjacencyEnabled(false)));
		repository.init();
		try (var connection = repository.getConnection()) {
			var vf = connection.getValueFactory();
			if (!test.empty) {
				connection.add(vf.createIRI("urn:values-oracle:a"), vf.createIRI("urn:values-oracle:p"),
						vf.createIRI("urn:values-oracle:b"));
			}
			if (test.predicateOnlyMissing) {
				connection.add(vf.createIRI("urn:values-oracle:a"), vf.createIRI("urn:values-oracle:missing"),
						vf.createIRI("urn:values-oracle:b"));
			}
			String query = PREFIX + test.query;
			System.out.println("ORACLE_QUERY " + test.name + "/" + mode + " " + query);
			TupleExpr parsed = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, query, null).getTupleExpr();
			printAlgebra("PARSED", parsed);
			var prepared = connection.prepareTupleQuery(query);
			Explanation explanation = prepared.explain(Explanation.Level.Optimized);
			if (explanation.tupleExpr() instanceof TupleExpr optimized) {
				printAlgebra("OPTIMIZED", optimized);
			}
			long compiled = LmdbNativeAggregateCompiler.COMPILED.get();
			long zeroOpens = ZeroLengthPathPlan.ENGAGED.get();
			long domains = ZeroLengthPathPlan.NODE_DOMAIN_OPENS.get();
			List<String> actual = QueryResults.asList(prepared.evaluate()).stream().map(this::rowKey).toList();
			System.out.println("ORACLE_RESULT " + test.name + "/" + mode + " expected=" + test.expected
					+ " actual=" + actual + " compiled=" + (LmdbNativeAggregateCompiler.COMPILED.get() - compiled)
					+ " zeroOpens=" + (ZeroLengthPathPlan.ENGAGED.get() - zeroOpens)
					+ " domainOpens=" + (ZeroLengthPathPlan.NODE_DOMAIN_OPENS.get() - domains));
			assertThat(actual).as("SPARQL graph-node Join oracle: %s/%s", test.name, mode)
					.containsExactlyInAnyOrderElementsOf(test.expected);
		}
	}

	private String rowKey(BindingSet row) {
		return row.getBindingNames()
				.stream()
				.sorted()
				.map(name -> name + "=" + row.getValue(name).stringValue())
				.collect(java.util.stream.Collectors.joining(";"));
	}

	private static void printAlgebra(String stage, TupleExpr expression) {
		List<String> variables = new ArrayList<>();
		expression.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Var variable) {
				variables.add(variable.getName() + "[hasValue=" + variable.hasValue() + ",constant="
						+ variable.isConstant() + ",value=" + variable.getValue() + "]");
			}
		});
		System.out.println(stage + "_ALGEBRA\n" + expression);
		System.out.println(stage + "_VARS " + variables);
	}
